(() => {
  'use strict';
  const L = window.L;
  if (!L) return;
  const page = document.getElementById('page');
  if (!page) return;
  const file = location.pathname.split('/').pop();
  const view = {step:1, supplier:new URLSearchParams(location.search).get('proveedor') || 's1', tab:'requests', selectedRfq:null, selectedOffer:null, selectedOrder:new URLSearchParams(location.search).get('pedido'), selectedCatalog:null, importRows:null, catalogEdit:null, catalogSearch:'',catalogFilter:'all',catalogSort:'name', draft:{supplierIds:[],deadline:future(7),notes:''}, error:'', stateBypass:false};
  const esc = value => L.escape(String(value ?? ''));
  const money = n => L.money(Number(n) || 0);
  const today = () => new Date().toISOString().slice(0,10);
  function future(days) { const date=new Date(); date.setDate(date.getDate()+days); return date.toISOString().slice(0,10); }
  const href = (f, extra={}) => L.href(f,extra);
  const link = (f,text,extra={},style='secondary') => `<a class="btn ${style}" href="${esc(href(f,extra))}">${esc(text)}</a>`;
  const button = (action,text,extra='',style='secondary') => `<button type="button" class="btn ${style}" data-action="${action}" ${extra}>${text}</button>`;
  const badge = (text,color='blue') => `<span class="badge ${color}">${esc(text)}</span>`;
  const state = () => L.state();
  function remember(values){const url=new URL(location.href);for(const [key,value] of Object.entries(values)){if(value==null)url.searchParams.delete(key);else url.searchParams.set(key,String(value));}history.replaceState({},'',url);document.querySelectorAll('.variant-picker a').forEach(a=>{const v=new URL(a.href).searchParams.get('v');a.href=L.href(L.page(),{v});});document.querySelectorAll('.sidebar .nav-link').forEach(a=>{a.href=L.href(new URL(a.href).pathname.split('/').pop());});}
  const project = s => s.projects.find(p=>p.id===new URLSearchParams(location.search).get('proyecto')) || s.projects.find(p=>p.id===s.activeProjectId) || s.projects[0];
  const supplier = (s,id) => s.suppliers.find(p=>p.id===id);
  const rfqsFor = (s,p) => s.rfqs.filter(r=>r.projectId===p.id);
  const statusLabel = val => ({DRAFT:'Borrador',SENT:'Enviado',SUBMITTED:'Presentada',ACCEPTED:'Adjudicada',CONFIRMED:'Confirmado',PARTIAL:'Recepción parcial',RECEIVED:'Recibido',CLOSED:'Cerrada'}[val] || val);
  const variant = () => L.variant();
  const field = (label,content) => `<label class="field"><span class="small">${label}</span>${content}</label>`;
  const empty = (title,body,actions='') => `<section class="card c-empty"><span class="c-eyebrow">Un siguiente paso claro</span><h2>${title}</h2><p class="muted">${body}</p><div class="row" style="justify-content:center">${actions}</div></section>`;
  function error(message) {view.error=message;const el=document.getElementById('commerce-error');if(el){el.textContent=message;el.hidden=false;el.scrollIntoView({block:'nearest',behavior:'smooth'});}else render();}
  function clearError(){view.error='';}
  function header(kicker,title,body,metric,label){return `<header class="c-hero"><div><div class="c-eyebrow">${kicker}</div><h1>${title}</h1><p>${body}</p></div>${metric!==undefined?`<div class="c-summary"><span class="c-eyebrow">${label}</span><strong class="c-big">${metric}</strong><span class="small muted">Datos ficticios · USD netos</span></div>`:''}</header>`;}
  function nav(){return `<div class="row" style="margin-bottom:20px">${link('d-engineering.html','1 · Revisar BOM')}${link('d-rfq.html','2 · Solicitar ofertas')}${link('d-supplier.html','3 · Responder como proveedor',{proveedor:view.supplier})}${link('d-comparison.html','4 · Comparar')}${link('d-orders.html','5 · Pedidos')}</div>`;}
  function steps(labels){return `<nav class="c-step-tabs" aria-label="Pasos">${labels.map((label,i)=>`<button type="button" data-action="step" data-step="${i+1}" aria-current="${view.step===i+1}"><span class="c-step-num">${i+1}</span>${label}</button>`).join('')}</nav>`;}
  function lineTable(lines){return `<div class="table-wrap"><table><thead><tr><th>Material / atributos requeridos</th><th>Cantidad solicitada</th><th>Revisión</th></tr></thead><tbody>${lines.map(l=>`<tr><td><strong>${esc(l.name)}</strong><span class="small muted">${esc(l.spec)}</span></td><td class="mono">${l.requiredQuantity ?? l.quantity} ${esc(l.unit || 'u')}</td><td>${badge(l.technicalApproved===false?'Pendiente':'Revisado',l.technicalApproved===false?'amber':'green')}</td></tr>`).join('')}</tbody></table></div>`;}
  function rfqSnapshot(p){return p.lines.map(l=>({...l,requiredQuantity:L.qty(l,p)}));}
  function supplierChecks(s){return s.suppliers.map(sp=>`<label class="check c-line"><input type="checkbox" name="suppliers" value="${esc(sp.id)}" ${view.draft.supplierIds.includes(sp.id)?'checked':''}><span><strong>${esc(sp.name)}</strong><span class="small muted">${esc(sp.city)} · Perfil ficticio, disponibilidad por confirmar</span></span></label>`).join('');}
  function rfqForm(s,p,compact=false){return `<form id="rfq-form"><h2>Invitar a cotizar</h2>${supplierChecks(s)}${field('Fecha límite para recibir respuestas',`<input name="deadline" type="date" min="${today()}" required value="${esc(view.draft.deadline)}">`)}${field('Condiciones y contexto para el proveedor',`<textarea name="notes" maxlength="1000" placeholder="Entrega en obra, precios netos, confirmar disponibilidad…">${esc(view.draft.notes)}</textarea>`)}<p class="small muted">Se envía una copia del BOM. No incluye tus costos de mano de obra, margen ni ofertas de competidores.</p><div class="c-actions"><button class="btn primary" type="submit">Crear y enviar solicitud</button>${compact?'':link('d-engineering.html','Volver a revisar')}</div></form>`;}
  function rfqHistory(s,p){const rows=rfqsFor(s,p);return `<section class="card"><div class="row between"><h2>Solicitudes del proyecto</h2>${badge(`${rows.length} enviadas`)}</div>${rows.length?rows.map(r=>`<article class="c-rfq-mini"><div><strong>${esc(r.id)}</strong> ${badge(statusLabel(r.status),r.projectVersion===p.version?'green':'amber')}<p class="small muted">${r.lines.length} materiales · ${r.supplierIds.length} proveedores · vence ${esc(r.deadline)} · BOM v${r.projectVersion}</p>${r.projectVersion!==p.version?'<p class="small">El BOM cambió: crear una solicitud actualizada antes de adjudicar.</p>':''}</div><div class="row">${button('rfq-csv','Descargar BOM',`data-id="${esc(r.id)}"`)}${link('d-supplier.html','Responder oferta',{rfq:r.id,proveedor:r.supplierIds[0]})}${link('d-comparison.html','Ver respuestas',{rfq:r.id})}</div></article>`).join(''):'<p class="muted">Todavía no hay solicitudes. Primero aprobá técnicamente el BOM y elegí proveedores.</p>'}</section>`;}
  function rfqPage(s,p){const reviewed=L.reviewed(p),lines=rfqSnapshot(p);const gate=reviewed?'<div class="c-gate good">BOM revisado y canónico confirmado. La solicitud guarda una copia de cantidades y atributos.</div>':`<div class="c-gate">Falta revisión humana de ${p.lines.filter(l=>!l.technicalApproved||l.canonicalStatus!=='confirmed').length} materiales. ${link('d-engineering.html','Resolver revisión')}</div>`;const hero=header('Compras / RFQ · Propuesta sobre flujo existente','Del BOM a una conversación precisa.','Invitá proveedores con cantidades efectivas y condiciones comunes. La solicitud es una propuesta local, sin envío de correo real.',lines.reduce((a,l)=>a+l.requiredQuantity,0),'Unidades en la solicitud');let content='';
    if(variant()==='guided'){content=`<div class="c-narrow">${steps(['Revisión','Proveedores','Enviar'])}${view.step===1?`<section class="card"><h2>01 / Una base técnica aprobada</h2>${gate}${lineTable(lines)}<div class="c-actions">${button('rfq-next','Continuar con proveedores','','primary')}</div></section>`:view.step===2?`<section class="card"><h2>02 / Elegir conversaciones</h2><p class="muted">Seleccioná al menos un proveedor. La ficha del directorio no garantiza stock.</p><div id="supplier-selection">${supplierChecks(s)}</div><div class="c-actions">${button('step','Volver','data-step="1"')}${button('rfq-next','Definir condiciones','','primary')}</div></section>`:`<section class="card">${gate}${rfqForm(s,p,true)}</section>`}${rfqHistory(s,p)}</div>`;}
    else if(variant()==='assisted'){content=`<div class="c-assist"><section class="card">${gate}${lineTable(lines)}${rfqForm(s,p)}</section><aside class="card c-dark"><span class="c-eyebrow">Asistencia / reglas locales</span><h2>Menos diferencias al comparar.</h2><p class="muted">Sugerencias deterministas a partir del BOM. No consulta IA ni garantiza compatibilidad.</p>${s.suppliers.map(sp=>`<article class="c-evidence"><span class="c-eyebrow">Evidencia: directorio</span><h3 style="color:#14231e">${esc(sp.name)}</h3><p style="color:#52644d">Ubicación ${esc(sp.city)}. Pedir precio y stock de las ${lines.length} líneas. No hay disponibilidad confirmada.</p>${button('suggest-supplier',view.draft.supplierIds.includes(sp.id)?'Invitado a la selección':'Agregar a selección',`data-id="${sp.id}"`)}</article>`).join('')}<p class="small muted">Podés elegir manualmente cualquier proveedor del formulario.</p></aside></div>${rfqHistory(s,p)}`;}
    else if(variant()==='visual'){content=`<div class="c-split"><section class="c-canvas"><div class="c-eyebrow">Mapa de solicitud / seleccioná un destino</div><div class="c-network"><div class="c-node c-node-center"><span class="small">BOM · versión ${p.version}</span><strong>${esc(p.name)}</strong><span>${lines.length} materiales / ×${p.multiplier}</span></div><div class="stack">${s.suppliers.map(sp=>`<button class="c-node c-node-line" data-action="suggest-supplier" data-id="${sp.id}" aria-pressed="${view.draft.supplierIds.includes(sp.id)}"><span class="small">${esc(sp.city)}</span><strong>${esc(sp.name)}</strong><span>${view.draft.supplierIds.includes(sp.id)?'Seleccionado':'Invitar a cotizar'}</span></button>`).join('')}</div></div><p class="c-chart-caption">El mapa muestra invitaciones, no relaciones comerciales verificadas. La tabla conserva todos los atributos.</p></section><section class="card">${gate}${rfqForm(s,p,true)}</section></div><section class="card">${lineTable(lines)}</section>${rfqHistory(s,p)}`;}
    else{content=`<div class="c-split"><section class="card">${gate}<div class="row between"><h2>BOM de la solicitud</h2>${badge(`Versión ${p.version}`)}</div>${lineTable(lines)}<div class="c-actions">${button('project-csv','Exportar cantidades')}${link('d-engineering.html','Abrir editor BOM')}</div></section><section class="card c-side">${rfqForm(s,p,true)}</section></div>${rfqHistory(s,p)}`;}
    return hero+nav()+content;}

  function ownCatalog(s){return s.catalog.filter(item=>item.supplierId===view.supplier);}
  function visibleCatalog(s){const term=view.catalogSearch.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es');return ownCatalog(s).filter(i=>`${i.name} ${i.spec} ${i.type}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es').includes(term)&&(view.catalogFilter==='all'||i.readingStatus===view.catalogFilter)).sort((a,b)=>view.catalogSort==='price-asc'?a.priceCents-b.priceCents:view.catalogSort==='price-desc'?b.priceCents-a.priceCents:a.name.localeCompare(b.name,'es'));}
  function catalogControls(s){return `<section class="c-catalog-controls" aria-label="Buscar, filtrar y ordenar catálogo propio">${field('Buscar en mis productos',`<input id="catalog-search" type="search" value="${esc(view.catalogSearch)}" placeholder="Nombre, especificación o tipo">`)}${field('Estado de lectura',`<select id="catalog-filter"><option value="all" ${view.catalogFilter==='all'?'selected':''}>Todas las lecturas</option><option value="PENDING" ${view.catalogFilter==='PENDING'?'selected':''}>Lectura pendiente</option><option value="READ" ${view.catalogFilter==='READ'?'selected':''}>Leído</option></select>`)}${field('Ordenar productos',`<select id="catalog-sort"><option value="name" ${view.catalogSort==='name'?'selected':''}>Nombre A → Z</option><option value="price-asc" ${view.catalogSort==='price-asc'?'selected':''}>Menor precio primero</option><option value="price-desc" ${view.catalogSort==='price-desc'?'selected':''}>Mayor precio primero</option></select>`)}<div><span class="small muted" role="status">${visibleCatalog(s).length} de ${ownCatalog(s).length} productos</span>${button('catalog-clear-filters','Limpiar filtros','','ghost')}</div></section>`;}
  function ownRfqs(s){return s.rfqs.filter(r=>r.supplierIds.includes(view.supplier)&&r.status==='SENT');}
  function selectedRfq(s){const wanted=view.selectedRfq || new URLSearchParams(location.search).get('rfq');return ownRfqs(s).find(r=>r.id===wanted) || ownRfqs(s).at(-1);}
  function offerFor(s,r){return r?s.offers.find(o=>o.rfqId===r.id&&o.supplierId===view.supplier):null;}
  function requestPicker(s){const rs=ownRfqs(s);return rs.length?field('Solicitud recibida',`<select id="rfq-picker">${rs.map(r=>`<option value="${esc(r.id)}" ${selectedRfq(s)?.id===r.id?'selected':''}>${esc(r.id)} · ${r.lines.length} materiales · ${esc(r.deadline)}</option>`).join('')}</select>`):'';}
  function offerForm(s,r){if(!r)return empty('Todavía no recibiste solicitudes.','La ingeniería debe revisar el BOM y enviar una solicitud a este proveedor.',link('d-rfq.html','Crear solicitud'));const o=offerFor(s,r);if(o?.status==='ACCEPTED')return `<section><h2>Oferta adjudicada</h2><p class="muted">La oferta ya originó un pedido. Sus precios se conservan como una copia.</p>${badge('Adjudicada','green')}${supplierOrders(s)}</section>`;return `<form id="offer-form" data-rfq="${esc(r.id)}"><div class="row between"><div><h2>Tu respuesta comercial</h2><p class="small muted">${esc(r.id)} · BOM v${r.projectVersion} · solo tus datos y condiciones</p></div>${badge(statusLabel(o?.status||'DRAFT'),o?.status==='SUBMITTED'?'green':'amber')}</div><div class="table-wrap"><table><thead><tr><th>Material solicitado</th><th>Cantidad</th><th>USD / u</th><th>Stock disponible</th><th>Confirmar</th></tr></thead><tbody>${r.lines.map(l=>{const item=o?.lines.find(x=>x.lineId===l.id);return `<tr><td><strong>${esc(l.name)}</strong><span class="small muted">${esc(l.spec)} · ${l.requiredQuantity} u requeridas</span><label class="field small">Proponer alternativa (opcional)<input name="alt-${l.id}" maxlength="120" value="${esc(item?.alternativeName||'')}" placeholder="Nombre + atributos equivalentes"></label></td><td><input aria-label="Cantidad ofertada de ${esc(l.name)}" type="number" min="0" step="1" name="qty-${l.id}" value="${item?.quantity??l.requiredQuantity}" required></td><td><input aria-label="Precio de ${esc(l.name)}" type="number" min="0" step="0.01" name="price-${l.id}" value="${((item?.priceCents??l.referenceCents??0)/100).toFixed(2)}" required></td><td><input aria-label="Stock de ${esc(l.name)}" type="number" min="0" step="1" name="stock-${l.id}" value="${item?.stockQuantity??0}" required></td><td><label class="check"><input type="checkbox" name="confirmed-${l.id}" ${item?.stockConfirmed?'checked':''}><span class="small">Stock verificado</span></label></td></tr>`;}).join('')}</tbody></table></div><div class="grid grid-3">${field('Oferta válida hasta',`<input name="validUntil" type="date" min="${today()}" required value="${esc(o?.validUntil||future(14))}">`)}${field('Plazo de entrega · días',`<input name="leadDays" type="number" min="0" max="365" step="1" value="${o?.leadDays??7}" required>`)}${field('Flete · USD netos',`<input name="shipping" type="number" min="0" step="0.01" value="${((o?.shippingCents??0)/100).toFixed(2)}" required>`)}</div>${field('Condiciones de pago',`<input name="paymentTerms" maxlength="160" required value="${esc(o?.paymentTerms||'Transferencia a 15 días')}">`)}${field('Observaciones para ingeniería',`<textarea name="notes" maxlength="1000">${esc(o?.notes||'')}</textarea>`)}<div class="c-disclosure">Los precios precargados son referencias ficticias, no ofertas aceptadas. Presentar requiere confirmar cantidad y stock de cada línea. Toda alternativa necesita aprobación humana posterior.</div><div class="c-actions"><button type="submit" name="intent" value="draft" class="btn secondary">Guardar borrador</button><button type="submit" name="intent" value="submit" class="btn primary">Presentar oferta</button>${o?button('offer-csv','Descargar mi oferta',`data-id="${esc(o.id)}"`):''}</div></form>`;}
  function supplierOrders(s){const orders=s.orders.filter(o=>o.supplierId===view.supplier);return `<div style="margin-top:25px"><h2>Pedidos para tu empresa</h2>${orders.length?orders.map(o=>`<article class="c-rfq-mini"><div><strong>${esc(o.id)}</strong> ${badge(statusLabel(o.status),o.status==='SENT'?'amber':'green')}<p class="small">${o.lines.length} materiales · ${money(o.totalCents)}</p><span class="small muted">Contacto de ingeniería visible después de aceptar.</span>${o.status!=='SENT'?'<p class="small">Contacto ficticio: Ana Torres · compras@ejemplo.test</p>':''}</div><div class="row">${o.status==='SENT'?button('supplier-accept','Aceptar pedido',`data-id="${esc(o.id)}"`,'primary'):''}${button('order-html','Descargar pedido',`data-id="${esc(o.id)}"`)}</div></article>`).join(''):'<p class="muted">Una adjudicación de ingeniería aparecerá aquí como pedido enviado.</p>'}</div>`;}
  function catalogTable(s){const items=visibleCatalog(s);return items.length?`<div class="table-wrap"><table><thead><tr><th>Mi producto</th><th>USD / u</th><th>Stock</th><th>Lectura</th><th>Acciones</th></tr></thead><tbody>${items.map(i=>`<tr><td><strong>${esc(i.name)}</strong><span class="small muted">${esc(i.spec)} · ${esc(i.type)}</span></td><td>${money(i.priceCents)}</td><td>${i.stock===null?'Sin confirmar':`${i.stock} u`}</td><td>${badge(i.canonicalStatus==='confirmed'?'Revisado':'Por revisar',i.canonicalStatus==='confirmed'?'green':'amber')}<span class="small muted">${i.readingStatus==='PENDING'?'Lectura pendiente':'Leído'}</span></td><td><div class="row">${button('catalog-edit','Editar',`data-id="${esc(i.id)}"`)}${button('catalog-review','Confirmar atributos',`data-id="${esc(i.id)}"`)}${button('catalog-delete','Eliminar',`data-id="${esc(i.id)}"`,'ghost')}</div></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><p class="muted">${ownCatalog(s).length?'No hay productos con esta búsqueda y estado.':'Tu catálogo está vacío. Creá un producto o importá una planilla CSV de demostración.'}</p>${ownCatalog(s).length?button('catalog-clear-filters','Mostrar todos los productos'):''}</div>`;}
  function catalogForm(s){const edit=ownCatalog(s).find(i=>i.id===view.catalogEdit);return `<form id="catalog-form" data-id="${esc(edit?.id||'')}"><h2>${edit?'Editar producto':'Agregar producto'}</h2>${field('Nombre comercial',`<input name="name" required maxlength="120" value="${esc(edit?.name||'')}">`)}${field('Especificación técnica',`<input name="spec" required maxlength="180" value="${esc(edit?.spec||'')}">`)}${field('Tipo de componente',`<input name="type" required maxlength="80" value="${esc(edit?.type||'')}">`)}<div class="grid grid-2">${field('USD por unidad',`<input name="price" type="number" required min="0.01" step="0.01" value="${edit?(edit.priceCents/100).toFixed(2):''}">`)}${field('Stock (vacío = sin confirmar)',`<input name="stock" type="number" min="0" step="1" value="${edit?.stock??''}">`)}</div><p class="small muted">Guardar deja los atributos pendientes de revisión manual. La lectura IA aquí se simula, no se paga ni se ejecuta.</p><div class="c-actions"><button class="btn primary" type="submit">${edit?'Guardar cambios':'Crear producto'}</button>${edit?button('catalog-cancel','Cancelar edición'):''}</div></form>`;}
  function importForm(){const rows=view.importRows;return `<section class="card"><h2>Importar y corregir antes de guardar</h2><p class="small muted">Propuesta local: CSV de 5 columnas. La app actual importa XLSX; este prototipo convierte la vista previa en un flujo editable offline.</p><form id="import-form">${field('Archivo CSV opcional',`<input type="file" id="import-file" accept=".csv,text/csv">`)}${field('nombre,especificación,tipo,precioUSD,stock',`<textarea id="import-text" name="csv" rows="4" placeholder="Interruptor,4P 25A 6kA,termomagnetico,42.00,60">${esc(view.importText||'')}</textarea>`)}<div class="row"><button class="btn secondary" type="submit">Revisar vista previa</button>${button('import-example','Usar ejemplo ficticio')}</div></form>${rows?`<div class="c-import-preview"><h3>Vista previa editable · ${rows.length} productos</h3><p class="small muted">Corregí columnas y confirmá atributos. No se elimina tu catálogo previo.</p><form id="import-confirm"><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Especificación</th><th>Tipo</th><th>USD</th><th>Stock</th><th>Revisión</th></tr></thead><tbody>${rows.map((r,n)=>`<tr>${['name','spec','type','price','stock'].map(k=>`<td><input aria-label="${k} fila ${n+1}" name="${k}-${n}" value="${esc(r[k])}" ${['price','stock'].includes(k)?`type="number" min="${k==='price'?'0.01':'0'}" step="${k==='price'?'0.01':'1'}"`:'maxlength="180"'} ${k==='stock'?'':'required'}></td>`).join('')}<td><label class="check"><input type="checkbox" name="reviewed-${n}" required><span class="small">Revisé</span></label></td></tr>`).join('')}</tbody></table></div><div class="c-actions"><button class="btn primary">Confirmar importación</button>${button('import-cancel','Descartar vista previa')}</div></form></div>`:''}</section>`;}
  function supplierPage(s,p){const sp=supplier(s,view.supplier)||s.suppliers[0];view.supplier=sp.id;const r=selectedRfq(s),items=ownCatalog(s),catalogItems=visibleCatalog(s);const picker=`<div class="row between"><div>${field('Identidad de proveedor ficticia',`<select id="supplier-picker">${s.suppliers.map(x=>`<option value="${x.id}" ${x.id===sp.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`)}</div><div class="c-note">Espacio privado: únicamente tu catálogo, tus ofertas y tus pedidos.</div></div>`;const hero=header('Proveedor / catálogo y respuesta','Cada oferta, con respaldo.','Precios, stock y condiciones bajo tu control. Cambiar la identidad recorre otra sesión ficticia; no comparte ofertas ni márgenes.',items.length,'Productos propios');const tabs=`<nav class="c-tablist">${button('supplier-tab','Solicitudes y ofertas',`data-tab="requests" aria-pressed="${view.tab==='requests'}"`)}${button('supplier-tab','Mi catálogo',`data-tab="catalog" aria-pressed="${view.tab==='catalog'}"`)}</nav>`;let content='';
    if(variant()==='guided'){content=`<div class="c-narrow">${steps(['Catálogo','Solicitud','Respuesta'])}${view.step===1?`${catalogControls(s)}<div class="grid grid-2"><section class="card">${catalogForm(s)}</section><section class="card"><h2>Tu catálogo</h2>${catalogTable(s)}${button('step','Ir a solicitud','data-step="2"','primary')}</section></div>${importForm()}`:view.step===2?`<section class="card">${requestPicker(s)}${r?lineTable(r.lines):empty('Sin solicitudes','Creá una solicitud desde ingeniería.',link('d-rfq.html','Ir a ingeniería'))}<div class="c-actions">${button('step','Revisar catálogo','data-step="1"')}${button('step','Responder oferta','data-step="3"','primary')}</div></section>`:`<section class="card">${requestPicker(s)}${offerForm(s,r)}${supplierOrders(s)}</section>`}</div>`;}
    else if(variant()==='assisted'){content=`${tabs}${view.tab==='catalog'?catalogControls(s):''}<div class="c-assist"><section class="card">${view.tab==='requests'?requestPicker(s)+offerForm(s,r)+supplierOrders(s):catalogTable(s)+catalogForm(s)}</section><aside class="card c-dark"><span class="c-eyebrow">Revisión sugerida / sin IA</span><h2>Confirmá lo que sabés.</h2><p class="muted">Ninguna sugerencia cambia atributos ni stock por su cuenta.</p>${items.filter(i=>i.canonicalStatus!=='confirmed').map(i=>`<article class="c-evidence"><span class="c-eyebrow">Origen: tu catálogo</span><h3 style="color:#14231e">${esc(i.name)}</h3><p style="color:#52644d">${esc(i.spec)}. La confirmación debe hacerse contra ficha técnica.</p>${button('catalog-edit','Revisar datos',`data-id="${i.id}"`)} ${button('catalog-review','Aprobar atributos',`data-id="${i.id}"`)}</article>`).join('')||'<p class="muted">No hay atributos pendientes en tu catálogo.</p>'}<div class="c-evidence"><span class="c-eyebrow">Chequeo de respuesta</span><p style="color:#52644d">Confirmá stock real y cantidades. No se infiere disponibilidad desde el precio de referencia.</p>${button('supplier-tab','Abrir respuesta manual','data-tab="requests"')}</div></aside></div>${view.tab==='catalog'?importForm():''}`;}
    else if(variant()==='visual'){content=`${tabs}${view.tab==='catalog'?`${catalogControls(s)}<div class="c-split"><section class="c-canvas"><span class="c-eyebrow">Estantería conceptual · no modelo CAD</span><div class="c-shelf">${catalogItems.map(i=>`<button data-action="catalog-select" data-id="${i.id}" aria-pressed="${view.selectedCatalog===i.id}"><div class="c-catalog-object"></div><strong>${esc(i.name)}</strong><p class="small">${money(i.priceCents)} · ${i.stock===null?'stock no confirmado':i.stock+' u'}</p></button>`).join('')||`<div><p>${ownCatalog(s).length?'No hay resultados en esta búsqueda.':'Tu estantería está vacía.'}</p>${button('catalog-clear-filters','Mostrar todos los productos')}</div>`}</div></section><section class="card">${catalogForm(s)}</section></div><section class="card">${catalogTable(s)}</section>${importForm()}`:`<div class="c-split"><section class="c-canvas"><span class="c-eyebrow">Mapa de solicitudes recibidas</span><div class="c-network"><div class="c-node c-node-center"><span class="small">Tu empresa</span><strong>${esc(sp.name)}</strong></div><div class="stack">${ownRfqs(s).map(x=>`<button class="c-node c-node-line" data-action="rfq-select" data-id="${x.id}" aria-pressed="${r?.id===x.id}"><span class="small">Vence ${esc(x.deadline)}</span><strong>${x.lines.length} materiales</strong><span>${esc(x.id)}</span></button>`).join('')||'<p>Sin solicitudes por ahora.</p>'}</div></div><p class="c-chart-caption">Cada nodo abre únicamente la solicitud que recibió este proveedor.</p></section><section class="card">${requestPicker(s)}<h2>Condiciones de la solicitud</h2><p class="muted">${esc(r?.notes||'Sin condiciones adicionales.')}</p><span class="small">No se comparten precios de otros proveedores.</span></section></div><section class="card">${offerForm(s,r)}${supplierOrders(s)}</section>`}`;}
    else{content=`${tabs}${view.tab==='requests'?`<section class="card">${requestPicker(s)}${offerForm(s,r)}${supplierOrders(s)}</section>`:`${catalogControls(s)}<div class="c-split"><section class="card"><div class="row between"><h2>Productos propios</h2>${button('catalog-csv','Exportar catálogo')}</div>${catalogTable(s)}</section><section class="card c-side">${catalogForm(s)}</section></div>${importForm()}`}`;}
    return hero+picker+content;}

  function comparisonRfq(s,p){const want=view.selectedRfq||new URLSearchParams(location.search).get('rfq');return rfqsFor(s,p).find(r=>r.id===want)||rfqsFor(s,p).at(-1);}
  function offeredTotal(o,r){return o.lines.reduce((sum,line)=>sum+line.quantity*line.priceCents,0)+(o.shippingCents||0);}
  function offerProblems(o,r,p,s){const issues=[];if(o.status!=='SUBMITTED')issues.push('La oferta aún no está presentada.');if(o.validUntil<today())issues.push('La oferta venció.');if(r.projectVersion!==p.version)issues.push('El BOM cambió desde la solicitud.');for(const wanted of r.lines){const l=o.lines.find(x=>x.lineId===wanted.id);if(!l||l.quantity!==wanted.requiredQuantity)issues.push(`Cantidad incompleta: ${wanted.name}.`);if(!l?.stockConfirmed||l.stockQuantity<wanted.requiredQuantity)issues.push(`Stock insuficiente o sin confirmar: ${wanted.name}.`);if(!l||l.priceCents<=0)issues.push(`Falta precio: ${wanted.name}.`);if(l?.alternativeId&&!p.alternatives.some(a=>a.id===l.alternativeId&&a.status==='approved'))issues.push(`Alternativa sin aprobación humana: ${wanted.name}.`);}if(s.orders.some(order=>order.offerId===o.id))issues.push('Esta oferta ya tiene pedido.');else if(s.orders.some(order=>order.rfqId===r.id))issues.push('Esta solicitud ya fue adjudicada. Creá otra solicitud para una compra adicional.');return issues;}
  function comparisonSelect(s,p){const r=comparisonRfq(s,p);return `<div class="row between"><div>${field('Solicitud a comparar',`<select id="comparison-rfq">${rfqsFor(s,p).map(x=>`<option value="${x.id}" ${x.id===r?.id?'selected':''}>${esc(x.id)} · BOM v${x.projectVersion}</option>`).join('')}</select>`)}</div><div class="row">${link('d-supplier.html','Completar otra oferta',{rfq:r?.id,proveedor:s.suppliers.find(x=>!s.offers.some(o=>o.rfqId===r?.id&&o.supplierId===x.id))?.id||'s2'})}${button('comparison-csv','Exportar comparación')}</div></div>`;}
  function alternativeReviews(o,p){const lines=o.lines.filter(l=>l.alternativeId);return lines.length?`<div style="margin-top:20px"><h3>Alternativas propuestas · decisión humana</h3>${lines.map(l=>{const alt=p.alternatives.find(a=>a.id===l.alternativeId);return `<article class="c-evidence"><span class="c-eyebrow">${esc(alt?.status==='approved'?'Aprobada por ingeniería':'Sin aprobación')}</span><h3>${esc(alt?.name||l.alternativeName)}</h3><p>${esc(alt?.reason||'Propuesta del proveedor: comprobar atributos, dimensiones y documentación antes de aprobar.')}</p>${alt?.status!=='approved'?`${button('approve-alt','Aprobar compatibilidad',`data-id="${esc(l.alternativeId)}"`,'primary')}${button('reject-alt','Rechazar',`data-id="${esc(l.alternativeId)}"`)}`:badge('Aprobación humana registrada','green')}</article>`;}).join('')}</div>`:'';}
  function orderForm(o,r,p,s){const problems=offerProblems(o,r,p,s);return `<div class="c-gate ${problems.length?'':'good'}">${problems.length?problems.map(x=>`<div>${esc(x)}</div>`).join(''):'Oferta vigente, cantidades y stock confirmados. Listo para emitir un pedido local.'}</div>${alternativeReviews(o,p)}<form id="order-form" data-offer="${esc(o.id)}" data-version="${s.version}">${field('Impuesto de demostración · % (sin asesoramiento fiscal)',`<input name="tax" type="number" min="0" max="100" step="0.01" value="0" required>`)}<label class="check"><input name="approved" type="checkbox" required><span class="small">Revisé condiciones, cantidades y compatibilidad. Autorizo el pedido ficticio.</span></label><div class="c-actions"><button class="btn primary" type="submit">Emitir pedido y descargar</button>${link('d-supplier.html','Revisar con proveedor',{proveedor:o.supplierId,rfq:r.id})}</div></form>`;}
  function offerCard(o,r,p,s){const sp=supplier(s,o.supplierId);const total=offeredTotal(o,r),issues=offerProblems(o,r,p,s);return `<article class="c-offer ${view.selectedOffer===o.id?'selected':''}"><div class="c-offer-head"><div><span class="c-eyebrow">Oferta ${esc(o.id)}</span><h2>${esc(sp?.name)}</h2>${badge(statusLabel(o.status),o.status==='SUBMITTED'?'green':'amber')}</div><strong class="c-big" style="font-size:28px">${money(total)}</strong></div><div class="c-offer-content"><div class="c-valid"><div><span class="small muted">Entrega</span><strong>${o.leadDays} días</strong></div><div><span class="small muted">Vigencia</span><strong>${esc(o.validUntil)}</strong></div><div><span class="small muted">Pago</span><strong>${esc(o.paymentTerms)}</strong></div><div><span class="small muted">Flete</span><strong>${money(o.shippingCents)}</strong></div></div><p class="small ${issues.length?'':'muted'}">${issues.length?esc(issues[0]):'Stock y cantidades confirmados para todas las líneas.'}</p>${button('offer-select','Revisar y adjudicar',`data-id="${o.id}"`,'primary')}${button('offer-csv','Exportar oferta',`data-id="${o.id}"`)}</div></article>`;}
  function matrix(offers,r,p,s){return `<section class="card"><div class="table-wrap"><table><thead><tr><th>Material / cantidad</th>${offers.map(o=>`<th>${esc(supplier(s,o.supplierId)?.name)}<br>${badge(statusLabel(o.status),o.status==='SUBMITTED'?'green':'amber')}</th>`).join('')}</tr></thead><tbody>${r.lines.map(l=>`<tr><td><strong>${esc(l.name)}</strong><span class="small muted">${esc(l.spec)} · ${l.requiredQuantity} u</span></td>${offers.map(o=>{const ol=o.lines.find(x=>x.lineId===l.id);return `<td><strong>${money(ol?.priceCents)} / u</strong><span class="small">${money((ol?.quantity||0)*(ol?.priceCents||0))} · ${ol?.quantity||0} u</span><span class="small muted">${ol?.stockConfirmed?'Stock confirmado':'Stock sin confirmar'} · ${ol?.stockQuantity||0} u disponibles</span>${ol?.alternativeId?badge('Alternativa','amber'):''}</td>`;}).join('')}</tr>`).join('')}<tr><td><strong>Materiales + flete / sin impuestos</strong></td>${offers.map(o=>`<td><strong>${money(offeredTotal(o,r))}</strong><span class="small">${o.leadDays} días · ${esc(o.paymentTerms)}</span>${button('offer-select','Elegir para revisar',`data-id="${o.id}"`)}</td>`).join('')}</tr></tbody></table></div></section>`;}
  function comparisonPage(s,p){const r=comparisonRfq(s,p);const hero=header('Decisión de compra / cotizaciones','Comparar sin perder el criterio.','La referencia más barata no es una recomendación técnica. Revisá stock, plazo, condiciones y alternativas antes de adjudicar.');if(!r)return hero+nav()+empty('Todavía no hay una solicitud.','Partí de un BOM revisado para que las ofertas comparen las mismas cantidades.',link('d-rfq.html','Crear solicitud'));const offers=s.offers.filter(o=>o.rfqId===r.id);if(!offers.length)return hero+nav()+comparisonSelect(s,p)+empty('Esperando la primera respuesta.','El proveedor puede preparar y presentar una oferta ficticia. No hay precio ni stock confirmado por defecto.',link('d-supplier.html','Responder como proveedor',{rfq:r.id,proveedor:r.supplierIds[0]}));const selected=offers.find(o=>o.id===view.selectedOffer)||offers.find(o=>o.supplierId===new URLSearchParams(location.search).get('proveedor'))||offers[0];const picker=comparisonSelect(s,p);let content='';
    if(variant()==='guided'){content=`<div class="c-narrow">${steps(['Ofertas','Validación','Pedido'])}${view.step===1?`${catalogControls(s)}<div class="grid grid-2">${offers.map(o=>offerCard(o,r,p,s)).join('')}</div><div class="c-actions">${button('step','Validar oferta seleccionada','data-step="2"','primary')}</div>`:view.step===2?`<section class="card"><h2>Validar ${esc(supplier(s,selected.supplierId)?.name)}</h2>${matrix([selected],r,p,s)}${alternativeReviews(selected,p)}<div class="c-actions">${button('step','Cambiar oferta','data-step="1"')}${button('step','Preparar pedido','data-step="3"','primary')}</div></section>`:`<section class="card"><h2>Pedido para ${esc(supplier(s,selected.supplierId)?.name)}</h2><strong class="c-big">${money(offeredTotal(selected,r))}</strong>${orderForm(selected,r,p,s)}</section>`}</div>`;}
    else if(variant()==='assisted'){const cheapest=offers.reduce((a,b)=>offeredTotal(a,r)<=offeredTotal(b,r)?a:b);content=`<div class="c-assist"><div>${matrix(offers,r,p,s)}<section class="card"><h2>Revisión de ${esc(supplier(s,selected.supplierId)?.name)}</h2>${orderForm(selected,r,p,s)}</section></div><aside class="card c-dark"><span class="c-eyebrow">Asistencia / regla transparente</span><h2>Recomendación comercial.</h2><article class="c-evidence"><span class="c-eyebrow">Origen: ofertas recibidas</span><h3 style="color:#14231e">Menor total: ${esc(supplier(s,cheapest.supplierId)?.name)}</h3><p style="color:#52644d">${money(offeredTotal(cheapest,r))}, incluyendo flete y excluyendo impuestos. No considera equivalencia técnica ni convierte monedas.</p>${button('offer-select','Revisar esta opción',`data-id="${cheapest.id}"`)}</article><p class="muted">Aprobar una alternativa es una decisión humana individual. Podés comparar y elegir manualmente desde la tabla.</p>${offers.map(o=>button('offer-select',esc(supplier(s,o.supplierId)?.name),`data-id="${o.id}"`)).join(' ')}</aside></div>`;}
    else if(variant()==='visual'){const max=Math.max(...offers.map(o=>offeredTotal(o,r)),1);content=`<div class="c-split"><section class="c-canvas"><span class="c-eyebrow">Balance de ofertas / total neto</span><h2 style="margin-top:14px">Elegí una barra para inspeccionar.</h2><div class="c-bars">${offers.map(o=>`<div class="c-price-row ${selected.id===o.id?'selected':''}"><button data-action="offer-select" data-id="${o.id}"><strong>${esc(supplier(s,o.supplierId)?.name)}</strong><span class="small">${o.leadDays} días</span></button><button data-action="offer-select" data-id="${o.id}" aria-label="Revisar ${esc(supplier(s,o.supplierId)?.name)}"><div class="c-price-track"><div class="c-price-fill" style="width:${Math.max(8,offeredTotal(o,r)/max*100)}%">${statusLabel(o.status)}</div></div></button><strong class="mono small">${money(offeredTotal(o,r))}</strong></div>`).join('')}</div><p class="c-chart-caption">Largo = materiales y flete. Stock, compatibilidad e impuestos se validan en el inspector, no en el gráfico.</p></section><section class="card"><h2>${esc(supplier(s,selected.supplierId)?.name)}</h2>${orderForm(selected,r,p,s)}</section></div>${matrix(offers,r,p,s)}`;}
    else{content=matrix(offers,r,p,s)+`<div class="c-split"><section class="card"><h2>Condiciones de la selección</h2><div class="grid grid-2"><div><span class="c-eyebrow">Proveedor</span><strong class="c-big" style="font-size:25px">${esc(supplier(s,selected.supplierId)?.name)}</strong></div><div><span class="c-eyebrow">Total sin impuesto</span><strong class="c-big">${money(offeredTotal(selected,r))}</strong></div></div><div class="c-valid"><div>Plazo<strong>${selected.leadDays} días</strong></div><div>Pago<strong>${esc(selected.paymentTerms)}</strong></div></div><p class="muted">${esc(selected.notes||'Sin observaciones adicionales.')}</p></section><section class="card">${orderForm(selected,r,p,s)}</section></div>`;}
    return hero+nav()+picker+content;}

  function orderDetail(o,s){return `<section class="card"><div class="row between"><div><span class="c-eyebrow">Orden local / ${esc(o.id)}</span><h2>${esc(supplier(s,o.supplierId)?.name)}</h2></div>${badge(statusLabel(o.status),o.status==='SENT'?'amber':'green')}</div><div class="table-wrap"><table><thead><tr><th>Material adjudicado</th><th>Cantidad</th><th>USD / u</th><th>Total neto</th></tr></thead><tbody>${o.lines.map(l=>`<tr><td>${esc(l.name)}</td><td class="mono">${l.quantity} u</td><td>${money(l.priceCents)}</td><td>${money(l.quantity*l.priceCents)}</td></tr>`).join('')}</tbody></table></div><div class="c-order-totals"><div class="c-line"><span>Materiales</span><strong>${money(o.materialsCents)}</strong></div><div class="c-line"><span>Flete</span><strong>${money(o.shippingCents)}</strong></div><div class="c-line"><span>Impuesto demo ${o.taxPercent}%</span><strong>${money(o.totalCents-o.materialsCents-o.shippingCents)}</strong></div><div class="c-line grand"><span>Total</span><strong>${money(o.totalCents)}</strong></div></div><div class="c-actions">${button('order-html','Descargar orden HTML',`data-id="${o.id}"`,'primary')}${button('order-csv','Descargar líneas CSV',`data-id="${o.id}"`)}${link('d-supplier.html','Abrir respuesta del proveedor',{proveedor:o.supplierId,rfq:o.rfqId})}${link('m-field.html','Recepción en obra',{pedido:o.id})}</div><p class="small muted">Documento ficticio. No es una factura ni confirma pago. El envío y la respuesta se simulan localmente.</p></section>`;}
  function orderPath(o){const index={SENT:0,CONFIRMED:1,PARTIAL:2,RECEIVED:3}[o.status]??0;return `<div class="c-order-path">${['Enviado','Confirmado','Recepción parcial','Recibido'].map((label,i)=>`<div class="c-order-stage ${i<index?'complete':''} ${i===index?'current':''}"><span>0${i+1}</span><strong>${label}</strong><span>${i<index?'Registrado':i===index?'Estado actual':'Siguiente etapa'}</span></div>`).join('')}</div>`;}
  function ordersPage(s,p){const os=s.orders.filter(o=>o.projectId===p.id),o=os.find(x=>x.id===view.selectedOrder)||os.at(-1);const hero=header('Compras / trazabilidad','Una decisión que sigue en obra.','Cada pedido conserva cantidades y precios adjudicados. El proveedor confirma la solicitud y obra registra recepciones parciales.',money(os.reduce((n,x)=>n+x.totalCents,0)),'Total en pedidos');if(!o)return hero+nav()+empty('Todavía no hay pedidos.','Compará una oferta presentada, confirmá stock y aprobá las alternativas antes de emitir el primer pedido.',link('d-comparison.html','Comparar ofertas'));let content='';const list=`<section class="card"><div class="row between"><h2>Pedidos del proyecto</h2>${button('orders-csv','Exportar todos')}</div><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Proveedor</th><th>Estado</th><th>Total</th><th>Detalle</th></tr></thead><tbody>${os.map(x=>`<tr><td class="mono">${esc(x.id)}</td><td>${esc(supplier(s,x.supplierId)?.name)}</td><td>${badge(statusLabel(x.status),x.status==='SENT'?'amber':'green')}</td><td>${money(x.totalCents)}</td><td>${button('order-select','Abrir',`data-id="${x.id}"`)}</td></tr>`).join('')}</tbody></table></div></section>`;
    if(variant()==='guided'){content=`<div class="c-narrow"><section class="card"><h2>El siguiente paso de ${esc(o.id)}</h2>${orderPath(o)}<p class="muted">${o.status==='SENT'?'El proveedor debe aceptar el pedido. Abrí su espacio para registrar la respuesta local.':o.status==='CONFIRMED'?'Pedido confirmado: obra puede registrar materiales recibidos.':'Revisá la recepción antes de cerrar el proyecto.'}</p><div class="row">${link('d-supplier.html','Respuesta del proveedor',{proveedor:o.supplierId,rfq:o.rfqId},'primary')}${link('m-field.html','Registrar recepción',{pedido:o.id})}</div></section>${orderDetail(o,s)}${list}</div>`;}
    else if(variant()==='assisted'){content=`<div class="c-assist"><div>${list}${orderDetail(o,s)}</div><aside class="card c-dark"><span class="c-eyebrow">Seguimiento / regla local</span><h2>Que nada quede sin respuesta.</h2><article class="c-evidence"><h3 style="color:#14231e">${o.status==='SENT'?'Confirmación pendiente':'Continuar en obra'}</h3><p style="color:#52644d">${o.status==='SENT'?'El estado es Enviado; no hay aceptación registrada. No se generó email real.':'La trazabilidad continúa con recepción parcial y revisión de faltantes.'}</p>${link(o.status==='SENT'?'d-supplier.html':'m-field.html',o.status==='SENT'?'Abrir proveedor':'Abrir recepción',{proveedor:o.supplierId,rfq:o.rfqId,pedido:o.id})}</article><p class="muted">La asistencia no confirma pedidos ni recepciones por sí sola.</p></aside></div>`;}
    else if(variant()==='visual'){content=`<section class="c-canvas"><span class="c-eyebrow">Mapa de la compra / estado local</span><div class="row between"><h2 style="margin-top:18px">${esc(o.id)} → ${esc(supplier(s,o.supplierId)?.name)}</h2><div class="row">${os.map(x=>button('order-select',esc(x.id),`data-id="${x.id}"`)).join('')}</div></div>${orderPath(o)}<div class="row">${link('d-supplier.html','Abrir confirmación',{proveedor:o.supplierId,rfq:o.rfqId})}${link('m-field.html','Abrir recepción',{pedido:o.id})}</div></section>${orderDetail(o,s)}${list}`;}
    else{content=list+orderDetail(o,s);}return hero+nav()+content;}

  function render(){const s=state(),p=project(s);if(!p){page.innerHTML=empty('No hay proyectos','Creá un proyecto para iniciar el recorrido.',link('d-projects.html','Crear proyecto'));return;}const special=new URLSearchParams(location.search).get('estado');if(special&&!view.stateBypass){const map={empty:['Sin datos en esta vista','Podés volver al recorrido con datos ficticios o crear una nueva solicitud.'],error:['No pudimos recuperar la vista','Error simulado sin llamadas a servicios. Tus datos locales se conservan.'],limit:['Consulta asistida no disponible','Este estado simula un límite. Todas las tareas comerciales pueden continuar manualmente.'],loading:['Preparando la vista','Cargando datos locales; no se llama a IA ni proveedores.']};const copy=map[special];if(copy){page.innerHTML=`<div class="commerce-page"><section class="card c-state">${special==='loading'?'<span class="c-spinner"></span>':''}<h1>${copy[0]}</h1><p class="muted">${copy[1]}</p>${button('recover',special==='limit'?'Continuar manualmente':'Volver al recorrido','','primary')}${link('d-rfq.html','Crear solicitud')}</section></div>`;if(special==='loading')window.setTimeout(()=>{view.stateBypass=true;render();},800);return;}}const content=file==='d-rfq.html'?rfqPage(s,p):file==='d-supplier.html'?supplierPage(s,p):file==='d-comparison.html'?comparisonPage(s,p):ordersPage(s,p);page.innerHTML=`<div class="commerce-page"><div id="commerce-error" role="alert" class="c-toast-error" ${view.error?'':'hidden'}>${esc(view.error)}</div>${content}</div>`;}
  function update(fn,description){L.update(fn,description);clearError();L.toast(description);render();}
  function rfqExport(r){L.download(`${r.id}-bom.csv`,L.csv([['Solicitud','Material','Especificación','Cantidad','Unidad'],...r.lines.map(l=>[r.id,l.name,l.spec,l.requiredQuantity,l.unit||'u'])]),'text/csv;charset=utf-8');}
  function offerExport(o){const s=state(),r=s.rfqs.find(x=>x.id===o.rfqId);L.download(`${o.id}-oferta.csv`,L.csv([['Proveedor','Material','Cantidad','Precio USD','Stock confirmado','Disponible','Alternativa'],...o.lines.map(l=>[supplier(s,o.supplierId)?.name,r?.lines.find(x=>x.id===l.lineId)?.name,l.quantity,(l.priceCents/100).toFixed(2),l.stockConfirmed?'Sí':'No',l.stockQuantity,l.alternativeName||''])]),'text/csv;charset=utf-8');}
  function orderExport(o,html=false){const s=state();if(html){const text=`<!doctype html><html lang="es"><meta charset="utf-8"><title>${esc(o.id)}</title><style>body{font:15px system-ui;max-width:900px;margin:50px auto;color:#183425}table{border-collapse:collapse;width:100%}th,td{padding:12px;border-bottom:1px solid #ddd;text-align:left}small{color:#687665}</style><h1>LIARD · Pedido ficticio ${esc(o.id)}</h1><p>Proveedor: ${esc(supplier(s,o.supplierId)?.name)} · Estado: ${esc(statusLabel(o.status))}</p><table><thead><tr><th>Material</th><th>Cantidad</th><th>USD/u</th><th>Total neto</th></tr></thead><tbody>${o.lines.map(l=>`<tr><td>${esc(l.name)}</td><td>${l.quantity}</td><td>${money(l.priceCents)}</td><td>${money(l.quantity*l.priceCents)}</td></tr>`).join('')}</tbody></table><p>Materiales: ${money(o.materialsCents)} · Flete: ${money(o.shippingCents)} · Impuesto demo: ${o.taxPercent}%</p><h2>Total: ${money(o.totalCents)}</h2><small>Datos ficticios. No es factura, comprobante de pago ni compromiso comercial real.</small></html>`;L.download(`${o.id}.html`,text,'text/html;charset=utf-8');}else L.download(`${o.id}.csv`,L.csv([['Pedido','Material','Cantidad','Precio USD','Total USD'],...o.lines.map(l=>[o.id,l.name,l.quantity,(l.priceCents/100).toFixed(2),(l.quantity*l.priceCents/100).toFixed(2)])]),'text/csv;charset=utf-8');}
  function parseCsv(text){const rows=[];let row=[],field='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){field+='"';i++;}else quote=!quote;}else if(c===','&&!quote){row.push(field.trim());field='';}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field.trim());if(row.some(x=>x))rows.push(row);row=[];field='';}else field+=c;}row.push(field.trim());if(row.some(x=>x))rows.push(row);if(quote)throw Error('Una comilla del CSV quedó abierta.');if(rows[0]?.[0]?.toLowerCase()==='nombre')rows.shift();if(!rows.length||rows.length>100)throw Error('Importá entre 1 y 100 productos.');if(rows.some(x=>x.length!==5))throw Error('Cada fila necesita exactamente 5 columnas: nombre, especificación, tipo, precio USD y stock.');return rows.map(x=>({name:x[0],spec:x[1],type:x[2],price:x[3],stock:x[4]}));}
  page.addEventListener('change',async event=>{const el=event.target;if(el.name==='suppliers'){view.draft.supplierIds=[...page.querySelectorAll('input[name=suppliers]:checked')].map(x=>x.value);}if(el.name==='deadline')view.draft.deadline=el.value;if(el.name==='notes'&&el.closest('#rfq-form'))view.draft.notes=el.value;if(el.id==='catalog-filter'){view.catalogFilter=el.value;render();}if(el.id==='catalog-sort'){view.catalogSort=el.value;render();}if(el.id==='supplier-picker'){view.supplier=el.value;remember({proveedor:view.supplier,rfq:null});view.selectedRfq=null;view.catalogEdit=null;view.selectedCatalog=null;view.importRows=null;view.catalogSearch='';view.catalogFilter='all';clearError();render();}if(el.id==='rfq-picker'){view.selectedRfq=el.value;remember({rfq:el.value});clearError();render();}if(el.id==='comparison-rfq'){view.selectedRfq=el.value;remember({rfq:el.value});view.selectedOffer=null;clearError();render();}if(el.id==='import-file'&&el.files[0]){const chosen=el.files[0];if(chosen.size>1024*1024){error('La demo admite CSV de hasta 1 MB.');el.value='';return;}try{view.importText=await chosen.text();const area=document.getElementById('import-text');if(area)area.value=view.importText;}catch{error('No se pudo leer el archivo. Podés pegar las filas manualmente.');}}});
  page.addEventListener('input',event=>{const el=event.target;if(el.name==='notes'&&el.closest('#rfq-form'))view.draft.notes=el.value;if(el.id==='import-text')view.importText=el.value;if(el.id==='catalog-search'){const cursor=el.selectionStart;view.catalogSearch=el.value;render();const next=document.getElementById('catalog-search');next?.focus();next?.setSelectionRange(cursor,cursor);}});
  page.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b||!page.contains(b))return;const action=b.dataset.action,id=b.dataset.id;const s=state(),p=project(s);clearError();try{
    if(action==='recover'){view.stateBypass=true;const url=new URL(location.href);url.searchParams.delete('estado');history.replaceState({},'',url);render();}
    else if(action==='step'){view.step=Number(b.dataset.step);render();}
    else if(action==='rfq-next'){if(view.step===1&&!L.reviewed(p))return error('Antes de continuar, aprobá técnicamente cada material del BOM.');if(view.step===2&&!view.draft.supplierIds.length)return error('Elegí al menos un proveedor para recibir la solicitud.');view.step=Math.min(3,view.step+1);render();}
    else if(action==='suggest-supplier'){view.draft.supplierIds=view.draft.supplierIds.includes(id)?view.draft.supplierIds.filter(x=>x!==id):[...view.draft.supplierIds,id];render();}
    else if(action==='rfq-csv'){const r=s.rfqs.find(x=>x.id===id);if(r)rfqExport(r);}
    else if(action==='project-csv'){L.download(`${p.id}-cantidades.csv`,L.csv([['Material','Especificación','Cantidad en plano','Multiplicador','Cantidad requerida'],...p.lines.map(l=>[l.name,l.spec,l.quantity,p.multiplier,L.qty(l,p)])]),'text/csv;charset=utf-8');}
    else if(action==='supplier-tab'){view.tab=b.dataset.tab;render();}
    else if(action==='rfq-select'){view.selectedRfq=id;remember({rfq:id});render();}
    else if(action==='catalog-edit'||action==='catalog-select'){if(!ownCatalog(s).some(x=>x.id===id))return error('Este producto no pertenece a tu catálogo.');view.catalogEdit=id;view.selectedCatalog=id;view.tab='catalog';if(variant()==='guided')view.step=1;render();document.getElementById('catalog-form')?.scrollIntoView({block:'nearest'});}
    else if(action==='catalog-clear-filters'){view.catalogSearch='';view.catalogFilter='all';view.catalogSort='name';render();}
    else if(action==='catalog-cancel'){view.catalogEdit=null;render();}
    else if(action==='catalog-delete'){update(st=>{const item=st.catalog.find(x=>x.id===id&&x.supplierId===view.supplier);if(!item)throw Error('Producto ajeno o eliminado.');st.catalog=st.catalog.filter(x=>x!==item);},'Producto eliminado del catálogo propio.');if(view.catalogEdit===id)view.catalogEdit=null;render();}
    else if(action==='catalog-review'){update(st=>{const item=st.catalog.find(x=>x.id===id&&x.supplierId===view.supplier);if(!item)throw Error('Producto ajeno o eliminado.');if(!item.spec||!item.type)throw Error('Completá especificación y tipo antes de aprobar.');item.canonicalStatus='confirmed';item.readingStatus='READ';item.updatedAt=new Date().toISOString();},'Atributos confirmados manualmente en catálogo propio.');}
    else if(action==='catalog-csv'){L.download(`${view.supplier}-catalogo.csv`,L.csv([['nombre','especificación','tipo','precioUSD','stock'],...ownCatalog(s).map(i=>[i.name,i.spec,i.type,(i.priceCents/100).toFixed(2),i.stock??''])]),'text/csv;charset=utf-8');}
    else if(action==='import-example'){view.importText='nombre,especificación,tipo,precioUSD,stock\nInterruptor modular,4P 25A 6kA,termomagnetico,42.00,60\nContactor de maniobra,3P 18A bobina 220V,contactor,53.00,18';render();}
    else if(action==='import-cancel'){view.importRows=null;render();}
    else if(action==='offer-select'){view.selectedOffer=id;remember({proveedor:s.offers.find(o=>o.id===id)?.supplierId});if(variant()==='guided')view.step=2;render();}
    else if(action==='offer-csv'){const o=s.offers.find(x=>x.id===id);if(o&&(file!=='d-supplier.html'||o.supplierId===view.supplier))offerExport(o);else error('Esta oferta no pertenece a tu proveedor.');}
    else if(action==='approve-alt'||action==='reject-alt'){update(st=>{const current=st.projects.find(x=>x.id===p.id);const alt=current?.alternatives.find(x=>x.id===id);if(!alt)throw Error('La alternativa ya no está disponible.');alt.status=action==='approve-alt'?'approved':'rejected';alt.reviewedBy='Ingeniería · decisión humana';alt.reviewedAt=new Date().toISOString();},action==='approve-alt'?'Compatibilidad de alternativa aprobada manualmente.':'Alternativa rechazada; revisar oferta con proveedor.');}
    else if(action==='comparison-csv'){const r=comparisonRfq(s,p);if(!r)return error('Primero creá una solicitud.');const offers=s.offers.filter(o=>o.rfqId===r.id);L.download(`${r.id}-comparacion.csv`,L.csv([['Proveedor','Estado','Total materiales y flete USD','Plazo días','Vigencia','Pago'],...offers.map(o=>[supplier(s,o.supplierId)?.name,statusLabel(o.status),(offeredTotal(o,r)/100).toFixed(2),o.leadDays,o.validUntil,o.paymentTerms])]),'text/csv;charset=utf-8');}
    else if(action==='order-select'){view.selectedOrder=id;remember({pedido:id});render();}
    else if(action==='order-html'||action==='order-csv'){const o=s.orders.find(x=>x.id===id);if(o&&(file!=='d-supplier.html'||o.supplierId===view.supplier))orderExport(o,action==='order-html');else error('Este pedido no pertenece a tu proveedor.');}
    else if(action==='orders-csv'){L.download(`${p.id}-pedidos.csv`,L.csv([['Pedido','Proveedor','Estado','Total USD'],...s.orders.filter(o=>o.projectId===p.id).map(o=>[o.id,supplier(s,o.supplierId)?.name,statusLabel(o.status),(o.totalCents/100).toFixed(2)])]),'text/csv;charset=utf-8');}
    else if(action==='supplier-accept'){update(st=>{const o=st.orders.find(x=>x.id===id&&x.supplierId===view.supplier);if(!o||o.status!=='SENT')throw Error('El pedido ya cambió de estado o pertenece a otro proveedor.');o.status='CONFIRMED';o.confirmedAt=new Date().toISOString();},'Proveedor confirmó el pedido local.');}
  }catch(e){error(e.message||'No se pudo completar la acción.');}});
  page.addEventListener('submit',event=>{const form=event.target;event.preventDefault();if(!form.reportValidity())return;clearError();const fd=new FormData(form);const s=state(),p=project(s);try{
    if(form.id==='rfq-form'){if(!L.reviewed(p))throw Error('La solicitud requiere todos los materiales revisados y su canónico confirmado.');const ids=fd.getAll('suppliers').filter(id=>s.suppliers.some(sp=>sp.id===id));if(!ids.length)throw Error('Elegí al menos un proveedor.');const deadline=String(fd.get('deadline'));if(deadline<today())throw Error('La fecha límite no puede estar en el pasado.');const id=L.uid('RFQ');update(st=>{const current=st.projects.find(x=>x.id===p.id);if(!L.reviewed(current))throw Error('El BOM cambió: revisá nuevamente antes de solicitar.');if(current.version!==p.version)throw Error('El BOM cambió en otra vista. Volvé a revisarlo.');st.rfqs.push({id,projectId:p.id,projectVersion:current.version,lines:rfqSnapshot(current),supplierIds:ids,deadline,notes:String(fd.get('notes')).trim(),status:'SENT',createdAt:new Date().toISOString()});},'Solicitud enviada localmente a proveedores seleccionados.');remember({rfq:id});view.step=1;view.draft.supplierIds=[];render();}
    else if(form.id==='catalog-form'){const id=form.dataset.id||L.uid('cat'),price=Math.round(Number(fd.get('price'))*100),stock=String(fd.get('stock')).trim()===''?null:Number(fd.get('stock'));if(!Number.isSafeInteger(price)||price<=0||stock!==null&&(!Number.isSafeInteger(stock)||stock<0))throw Error('Precio y stock deben ser valores válidos; stock entero no negativo.');const data={id,supplierId:view.supplier,name:String(fd.get('name')).trim(),spec:String(fd.get('spec')).trim(),type:String(fd.get('type')).trim(),priceCents:price,stock,currency:'USD',readingStatus:'PENDING',canonicalStatus:'suggested',updatedAt:new Date().toISOString()};if(!data.name||!data.spec||!data.type)throw Error('Completá nombre, especificación y tipo.');update(st=>{if(form.dataset.id){const item=st.catalog.find(x=>x.id===id&&x.supplierId===view.supplier);if(!item)throw Error('El producto cambió o pertenece a otro proveedor.');Object.assign(item,data);}else st.catalog.push(data);},form.dataset.id?'Producto actualizado; revisar atributos.':'Producto creado en catálogo propio.');view.catalogEdit=null;render();}
    else if(form.id==='import-form'){view.importText=String(fd.get('csv'));view.importRows=parseCsv(view.importText);render();}
    else if(form.id==='import-confirm'){const items=view.importRows.map((r,n)=>{const stockText=String(fd.get(`stock-${n}`)).trim(),stock=stockText===''?null:Number(stockText),price=Math.round(Number(fd.get(`price-${n}`))*100);const name=String(fd.get(`name-${n}`)).trim(),spec=String(fd.get(`spec-${n}`)).trim(),type=String(fd.get(`type-${n}`)).trim();if(!name||!spec||!type||!Number.isSafeInteger(price)||price<=0||stock!==null&&(!Number.isSafeInteger(stock)||stock<0)||!fd.get(`reviewed-${n}`))throw Error(`Revisá los campos de la fila ${n+1}.`);return {id:L.uid('cat'),supplierId:view.supplier,name,spec,type,priceCents:price,stock,currency:'USD',readingStatus:'READ',canonicalStatus:'confirmed',updatedAt:new Date().toISOString()};});update(st=>{st.catalog.push(...items);},`${items.length} productos importados y revisados manualmente.`);view.importRows=null;view.importText='';render();}
    else if(form.id==='offer-form'){const r=s.rfqs.find(x=>x.id===form.dataset.rfq&&x.supplierIds.includes(view.supplier));if(!r)throw Error('La solicitud no pertenece a tu proveedor.');const old=offerFor(s,r);if(old?.status==='ACCEPTED')throw Error('La oferta ya fue adjudicada y no puede editarse.');const intent=event.submitter?.value||'draft';const lines=r.lines.map(l=>{const quantity=Number(fd.get(`qty-${l.id}`)),priceCents=Math.round(Number(fd.get(`price-${l.id}`))*100),stockQuantity=Number(fd.get(`stock-${l.id}`)),stockConfirmed=!!fd.get(`confirmed-${l.id}`),alternativeName=String(fd.get(`alt-${l.id}`)).trim();if(!Number.isSafeInteger(quantity)||quantity<0||!Number.isSafeInteger(stockQuantity)||stockQuantity<0||!Number.isSafeInteger(priceCents)||priceCents<0)throw Error('Usá cantidades y stock enteros; precio no negativo.');if(intent==='submit'&&(quantity!==l.requiredQuantity||priceCents<=0||!stockConfirmed||stockQuantity<quantity))throw Error(`Para presentar, confirmá cantidad completa, precio y stock suficiente de ${l.name}.`);const previous=old?.lines.find(x=>x.lineId===l.id);return {lineId:l.id,quantity,priceCents,stockQuantity,stockConfirmed,alternativeName,alternativeId:alternativeName&&previous?.alternativeName===alternativeName?previous.alternativeId:null};});const validUntil=String(fd.get('validUntil'));if(validUntil<today())throw Error('La oferta debe estar vigente.');const shippingCents=Math.round(Number(fd.get('shipping'))*100),leadDays=Number(fd.get('leadDays'));if(!Number.isSafeInteger(shippingCents)||shippingCents<0||!Number.isSafeInteger(leadDays)||leadDays<0)throw Error('Revisá flete y plazo de entrega.');const id=old?.id||L.uid('oferta');update(st=>{const current=st.offers.find(x=>x.id===id);if(current&&(current.status==='ACCEPTED'||current.revision!==old?.revision))throw Error('La oferta cambió en otra vista. Recargá para revisar la nueva versión.');const ownerProject=st.projects.find(x=>x.id===r.projectId);for(const line of lines){if(line.alternativeName&&!line.alternativeId){line.alternativeId=L.uid('alt');ownerProject.alternatives.push({id:line.alternativeId,lineId:line.lineId,name:line.alternativeName,spec:r.lines.find(x=>x.id===line.lineId)?.spec||'',referenceCents:line.priceCents,status:'suggested',reason:'Propuesta del proveedor. Ingeniería debe comprobar equivalencia y documentación.'});}}const next={id,rfqId:r.id,supplierId:view.supplier,status:intent==='submit'?'SUBMITTED':'DRAFT',validUntil,leadDays,paymentTerms:String(fd.get('paymentTerms')).trim(),shippingCents,lines,notes:String(fd.get('notes')).trim(),revision:(current?.revision||0)+1};if(current)Object.assign(current,next);else st.offers.push(next);},intent==='submit'?'Oferta presentada con stock confirmado.':'Borrador de oferta guardado.');}
    else if(form.id==='order-form'){if(!fd.get('approved'))throw Error('Confirmá la revisión humana antes de emitir.');const taxPercent=Number(fd.get('tax'));if(!Number.isFinite(taxPercent)||taxPercent<0||taxPercent>100)throw Error('El impuesto de demo debe estar entre 0 y 100%.');let order;update(st=>{if(st.version!==Number(form.dataset.version))throw Error('Los datos cambiaron en otra vista. Revisá las condiciones actualizadas antes de emitir.');const o=st.offers.find(x=>x.id===form.dataset.offer),r=st.rfqs.find(x=>x.id===o?.rfqId),current=st.projects.find(x=>x.id===r?.projectId);if(!o||!r||!current)throw Error('Oferta o solicitud ya no disponible.');const issues=offerProblems(o,r,current,st);if(issues.length)throw Error(issues.join(' '));const lines=o.lines.map(l=>({lineId:l.lineId,name:l.alternativeName||r.lines.find(x=>x.id===l.lineId)?.name||'Material',quantity:l.quantity,priceCents:l.priceCents}));const materialsCents=lines.reduce((a,l)=>a+l.quantity*l.priceCents,0),shippingCents=o.shippingCents||0;order={id:L.uid('OC'),rfqId:r.id,offerId:o.id,projectId:r.projectId,supplierId:o.supplierId,status:'SENT',lines,materialsCents,shippingCents,taxPercent,totalCents:Math.round((materialsCents+shippingCents)*(1+taxPercent/100)),createdAt:new Date().toISOString()};st.orders.push(order);o.status='ACCEPTED';},'Pedido emitido localmente; esperando confirmación del proveedor.');orderExport(order,true);location.href=href('d-orders.html',{pedido:order.id});}
  }catch(e){error(e.message||'No se pudo guardar. Revisá los campos.');}});
  L.subscribe(render);
  render();
})();
